using System;using System.IO;using System.Linq;using System.Collections;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;using UnityEngine.UI;using UnityEngine.SceneManagement;using UnityEngine.TestTools;
namespace IdleIntelligence.PlayTests
{
 public sealed class AdUITests
 {
  string dir;GameRuntime game;
  [UnitySetUp]public IEnumerator Setup(){dir=Path.Combine(Path.GetTempPath(),"unity-ad-ui-"+Guid.NewGuid());Directory.CreateDirectory(dir);GameRuntime.SavePathOverride=Path.Combine(dir,"save.json");yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();}
  [UnityTearDown]public IEnumerator Cleanup(){if(game!=null)UnityEngine.Object.Destroy(game.gameObject);yield return null;GameRuntime.SavePathOverride=null;Directory.Delete(dir,true);}
  static void Click(string name){var b=GameObject.Find(name)?.GetComponent<Button>();Assert.That(b,Is.Not.Null,name);Assert.That(b.interactable,Is.True,name);b.onClick.Invoke();}
  IEnumerator Open(){Click("ResearchTab");yield return null;Click("AdAccess");yield return null;}
  [UnityTest]public IEnumerator UnavailableProviderNeverRewardsAndGemConfirmationCompletesActualJobOnce()
  {Debug.Log("FUNDED_AD_UI: Gems and data prepared, actual paid research/skip; no successful ad provider");game.Act(s=>{var n=s.Copy();n.Retention.gems=10000;n.Data=ScientificNumber.From(100000);return Game.Research(n,"dataGeneration");});yield return Open();long gems=game.State.Retention.gems;Click("AdClaim-gems-0");yield return null;Assert.That(game.State.Retention.gems,Is.EqualTo(gems));Assert.That(game.State.Ads.hasPending,Is.False);Assert.That(game.State.Ads.counts,Is.All.Zero);Click("AdGemSkip-0");yield return null;long cost=AdRewards.SkipQuote(game.State,0).Cost;var button=GameObject.Find("AdSkipConfirm").GetComponent<Button>();button.onClick.Invoke();button.onClick.Invoke();Assert.That(game.State.ResearchJob,Is.Null);Assert.That(game.State.Retention.gems,Is.EqualTo(gems-cost));Assert.That(Game.Level(game.State,"dataGeneration"),Is.EqualTo(1));yield return null;foreach(int width in new[]{320,390,430})WorkshopTests.Capture(width,width==320?568:width==390?844:932,"/tmp/unity-ad-unavailable-"+width+".png");}
  [UnityTest]public IEnumerator RapidDirectClaimsAcrossMarketAndCapsuleOnlyConsumeOneRequest()
  {game.Act(s=>{var n=s.Copy();n.Rewards.owned=new[]{"ai_singularity.pass.adfree"};n.Prestige.resets=1;return n;});Click("ResearchTab");yield return null;Click("MarketAccess");yield return null;var market=GameObject.Find("MarketVideo").GetComponent<Button>();market.onClick.Invoke();market.onClick.Invoke();Assert.That(game.State.Market.adWindowUsed,Is.EqualTo(1));yield return null;Click("ResearchTab");yield return null;Click("GemAccess");yield return null;Click("GemPage-capsule");yield return null;var capsule=GameObject.Find("CapsuleVideo").GetComponent<Button>();capsule.onClick.Invoke();capsule.onClick.Invoke();Assert.That(game.State.Capsules.videos,Is.EqualTo(1));Assert.That(game.State.Capsules.draws,Is.EqualTo(1));}
  [UnityTest]public IEnumerator VerifiedAdFreeRightUsesDirectClaimsWithLimitsAndNoProviderSuccess()
  {Debug.Log("PREPARED_ENTITLEMENT_TEST_ONLY: authenticated ownership injected, no real purchase");game.Act(s=>{var n=s.Copy();n.Rewards.owned=new[]{"ai_singularity.pass.adfree"};return n;});yield return Open();long gems=game.State.Retention.gems;Click("AdClaim-gems-0");yield return null;Assert.That(game.State.Retention.gems,Is.EqualTo(gems+(long)AdBalance.RewardGems));Assert.That(game.State.Ads.counts[0],Is.EqualTo(1));Assert.That(game.State.Ads.hasPending,Is.False);Assert.That(GameObject.Find("AdNotice").GetComponent<Text>().text,Does.Contain("Keine Anzeige abgespielt"));var load=new AtomicSaveStore(game.SavePath,new UnitySaveCodec()).Load(game.State.SavedAt);Assert.That(load.Writable,Is.True,load.Message);Assert.That(load.State.Ads.counts[0],Is.EqualTo(1));Assert.That(load.State.Rewards.transactions.Length,Is.EqualTo(1));}
 }
}
